\copy (SELECT ns.race_key, ns.rank_key, ns.status, ns.origin, ns.is_confident, ns.confident_ev, ns.submitted_at, ns.published_at, ns.deleted_at, ns.cancel_reason, ns.netkeirin_race_id, ns.netkeirin_item_id, ns.settled_fp, ns.settled_bet, ns.settled_payout, ns.settled_hit, ns.settled_n_combos, ns.settled_at, wr.race_date, wr.n_entries, wr.race_type, ns.bet_detail FROM keirin.netkeirin_submissions ns LEFT JOIN keirin.wt_races wr ON wr.race_key=ns.race_key) TO 'subs.csv' WITH CSV HEADER
